// 1 item = 1 batch = 1 ข้อความ Discord — เดิม node นี้หั่นข้อความเป็น section ละ
// ข้อความ (header/ไทม์ไลน์/เหตุผล/เตรียมตัว/แนะนำ) เพราะ content ธรรมดาจำกัด 2000
// ตัวอักษร ทำให้ตอนมี 2 batch active ยิงรัวติดกันได้ถึง 12 ข้อความ และมีแค่ข้อความแรก
// ของแต่ละ batch ที่บอกชื่อเบียร์ ท่อนที่เหลือลอยเปล่าๆ แยกไม่ออกว่าของตัวไหน
// ตอนนี้ใช้ embed (รวมได้ 6000 ตัวอักษร + มีแถบสี/title เป็นขอบเขตให้เอง) จึงจบใน
// ข้อความเดียวต่อ batch — embed ถูกสร้างที่ Phase Analysis Engine เพื่อให้หน้าตา
// ตรงกับ /ferment_status เป๊ะ ที่นี่แค่ห่อส่งต่อพร้อมข้อมูลที่ปุ่ม "ปรับ target" ต้องใช้
const results = [];
$input.all().forEach((it) => {
  const d = it.json;
  const out = {
    batch_id: d.batch_id,
    recommended_controller_target_c: d.recommended_controller_target_c,
    recommended_pill_temp_c: d.recommended_pill_temp_c,
    next_phase: d.next_phase
  };
  if (Array.isArray(d.discord_embeds) && d.discord_embeds.length) {
    out.embeds = d.discord_embeds;
  } else {
    // fallback ข้อความล้วน เผื่อ import workflow นี้ใหม่แล้วลืม import Phase Analysis
    // Engine ตาม (เคยพลาด import ไม่ครบมาแล้ว) — หน้าตาไม่สวยแต่ยังได้ข้อมูลครบ
    // ดีกว่า Discord ตีกลับทั้งข้อความเพราะไม่มีทั้ง content และ embeds
    out.content = '📋 อัปเดตสถานะ: ' + (d.beer_name || '(ไม่ระบุชื่อ)')
      + '\nเฟส: ' + (d.detected_phase || '-')
      + (d.reasoning ? ('\n' + d.reasoning) : '');
  }
  results.push({ json: out });
});
return results;

// เวลาอ้างอิงสำหรับให้ sub-workflow วิเคราะห์เฟส ("Phase Analysis Engine")
// ใช้คิด hoursSinceStart และอัตราไต่อุณหภูมิ Pill ช่วง 6 ชม.ล่าสุด (ETA) — cron จริง
// ใช้เวลาปัจจุบันจริงเสมอ ต่างจาก Phase Analysis Backtest ที่ stamp เป็น cutoff
// จำลองแทน (ดู Phase Analysis Backtest.json's node เดียวกันนี้)
const items = $input.all();
return items.map((it) => ({
  json: {
    ...it.json,
    analysis_time_iso: new Date().toISOString()
  }
}));

// loop ทุก item (1 item = 1 batch active) ตามกฎ $input.all() — สร้างข้อความเตือนเฉพาะ
// sensor ที่เงียบเกิน threshold แล้วเท่านั้น ถ้าไม่มีตัวไหนเงียบ return [] (HTTP node
// ถัดไปจะไม่ยิงอะไรเลย)
// threshold 6 ชม. = ขาดข้อมูลเกิน 1 รอบ cron เต็มๆ (cron รันทุก 4 ชม. + RAPT รายงานทุก
// ~15-45 นาที) — ตั้งสูงไว้กัน false positive จากจังหวะ fetch/ลำดับ branch เพราะถึง
// sensor แค่สะดุดชั่วคราวก็ไม่ควรแจ้งเตือนพร่ำเพรื่อ
const THRESHOLD_H = 6;
const items = $input.all();
const results = [];
items.forEach((it) => {
  const d = it.json;
  const problems = [];
  if (d.pill_age_h == null) {
    problems.push('Pill "' + (d.pill_name || '-') + '" ไม่มีข้อมูลเลย');
  } else if (Number(d.pill_age_h) > THRESHOLD_H) {
    problems.push('Pill "' + (d.pill_name || '-') + '" เงียบมา ' + Number(d.pill_age_h).toFixed(1) + ' ชม.');
  }
  if (d.ctrl_age_h == null) {
    problems.push('ตู้ควบคุม "' + (d.controller_name || '-') + '" ไม่มีข้อมูลเลย');
  } else if (Number(d.ctrl_age_h) > THRESHOLD_H) {
    problems.push('ตู้ควบคุม "' + (d.controller_name || '-') + '" เงียบมา ' + Number(d.ctrl_age_h).toFixed(1) + ' ชม.');
  }
  if (problems.length) {
    results.push({
      json: {
        content: '📡 เซ็นเซอร์ไม่ส่งข้อมูล — ' + d.beer_name + ':\n• ' + problems.join('\n• ') + '\nเช็คแบต Pill / WiFi / ปลั๊กตู้ควบคุม แล้วดูใน RAPT portal ว่า device ยัง online ไหม'
      }
    });
  }
});
return results;
